import{_ as d,o as e,c as r,a5 as a}from"./chunks/framework.bIR-4glx.js";const p=JSON.parse('{"title":"语法证据卡：从规则识别到真实表达","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/grammar-evidence.zh.md","filePath":"public/downloads/worksheets/grammar-evidence.zh.md","lastUpdated":1795488252000}'),h={name:"public/downloads/worksheets/grammar-evidence.zh.md"};function i(l,t,n,o,b,s){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="语法证据卡-从规则识别到真实表达" tabindex="-1">语法证据卡：从规则识别到真实表达 <a class="header-anchor" href="#语法证据卡-从规则识别到真实表达" aria-label="Permalink to &quot;语法证据卡：从规则识别到真实表达&quot;">​</a></h1><p>这张卡每次只追踪一个高影响结构。复制到私有笔记，保留原始句子与修改理由。不要记录客户、公司、学校、医疗或第三方的敏感内容；使用合成事实或最小化片段练习。</p><h2 id="_1-定义真实任务" tabindex="-1">1. 定义真实任务 <a class="header-anchor" href="#_1-定义真实任务" aria-label="Permalink to &quot;1. 定义真实任务&quot;">​</a></h2><p>日期：<br> 场景：邮件 / 说明 / 对话 / 复述 / 面试 / 其他<br> 受众：<br> 任务必须让对方理解或完成什么：<br> 时间、工具和长度限制：<br> 原始样本位置：</p><h2 id="_2-找到一个结构问题" tabindex="-1">2. 找到一个结构问题 <a class="header-anchor" href="#_2-找到一个结构问题" aria-label="Permalink to &quot;2. 找到一个结构问题&quot;">​</a></h2><p>我的原句/片段：<br> 对方最可能理解成：<br> 我真正想表达：<br> 影响类型：意思改变 / 任务阻断 / 高频重复 / 语域不合 / 低影响<br> 本轮只追踪的结构：</p><table tabindex="0"><thead><tr><th>样本</th><th>结构选择</th><th>表达的现实关系</th><th>是否符合任务</th></tr></thead><tbody><tr><td>原句</td><td></td><td></td><td></td></tr><tr><td>对比 A</td><td></td><td></td><td></td></tr><tr><td>对比 B</td><td></td><td></td><td></td></tr></tbody></table><h2 id="_3-写一张意义对比卡" tabindex="-1">3. 写一张意义对比卡 <a class="header-anchor" href="#_3-写一张意义对比卡" aria-label="Permalink to &quot;3. 写一张意义对比卡&quot;">​</a></h2><p>我要表达的意义：<br> 容易混淆的形式：<br> 来自可靠材料的例句与来源：<br> 一句自己的解释：<br> 反例或适用边界：</p><p>解释应回答“为什么这个形式适合这个事实”，而不是只复制术语定义。</p><h2 id="_4-保存修改与理由" tabindex="-1">4. 保存修改与理由 <a class="header-anchor" href="#_4-保存修改与理由" aria-label="Permalink to &quot;4. 保存修改与理由&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>条件</th><th>句子/输出位置</th><th>修改了什么</th><th>为什么</th></tr></thead><tbody><tr><td>首版</td><td>无提示</td><td></td><td></td><td></td></tr><tr><td>修改版</td><td>看过讲解/反馈</td><td></td><td></td><td></td></tr><tr><td>独立重做</td><td>合上材料</td><td></td><td></td><td></td></tr></tbody></table><p>修改后对方如何理解：<br> 仍然影响任务的问题：<br> 被建议但我没有采纳的风格修改：</p><h2 id="_5-在四项能力中调用" tabindex="-1">5. 在四项能力中调用 <a class="header-anchor" href="#_5-在四项能力中调用" aria-label="Permalink to &quot;5. 在四项能力中调用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>小任务</th><th>结果</th><th>证据</th></tr></thead><tbody><tr><td>听力</td><td>听出同一结构承担的关系</td><td></td><td></td></tr><tr><td>阅读</td><td>标出范围、指向或逻辑连接</td><td></td><td></td></tr><tr><td>口语</td><td>限时使用并在出错后修复</td><td></td><td></td></tr><tr><td>写作</td><td>比较两个版本对读者理解的影响</td><td></td><td></td></tr></tbody></table><p>不必每轮都完成四项。至少保留一项输入观察和一项主动输出。</p><h2 id="_6-ai-与反馈记录" tabindex="-1">6. AI 与反馈记录 <a class="header-anchor" href="#_6-ai-与反馈记录" aria-label="Permalink to &quot;6. AI 与反馈记录&quot;">​</a></h2><p>工具/反馈者与日期：<br> 它观察到的问题：<br> 它给出的解释：<br> 它是否区分错误、歧义、语域和风格：<br> 我如何用词典、语料、教师或读者复核：<br> 我采纳/拒绝什么，为什么：</p><h2 id="_7-延迟复测" tabindex="-1">7. 延迟复测 <a class="header-anchor" href="#_7-延迟复测" aria-label="Permalink to &quot;7. 延迟复测&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间点</th><th>提示条件</th><th>新任务</th><th>独立选择</th><th>结果</th></tr></thead><tbody><tr><td>第 1 天</td><td>原任务、无提示</td><td></td><td></td><td></td></tr><tr><td>第 3–7 天</td><td>撤掉规则与原答案</td><td>平行主题</td><td></td><td></td></tr><tr><td>第 14 天</td><td>新受众或时间压力</td><td>迁移任务</td><td></td><td></td></tr></tbody></table><p>第 7 天仍然保留的判断：<br> 再次出现的错误：<br> 换条件后失败在哪里：</p><h2 id="_8-评分与去留" tabindex="-1">8. 评分与去留 <a class="header-anchor" href="#_8-评分与去留" aria-label="Permalink to &quot;8. 评分与去留&quot;">​</a></h2><p>每项 0–2：<code>0=未完成</code>，<code>1=依赖提示或不稳定</code>，<code>2=当前条件下完成</code>。</p><table tabindex="0"><thead><tr><th>项目</th><th style="text-align:right;">第 1 天</th><th style="text-align:right;">第 7 天</th><th style="text-align:right;">第 14 天</th><th>证据理由</th></tr></thead><tbody><tr><td>能说明形式与意义差异</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>能在新句子中识别</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>能在输出中调用</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>出错后能自我修复</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>不再持续改变关键意思</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr></tbody></table><p>当前最支持：继续同一结构 / 增加变式 / 转向另一问题 / 暂停<br> 依据：<br> 仍不能推出的结论：<br> 下一项最小任务：<br> 下一次复查日期：</p><p>相关章节：<a href="https://byoungd.github.io/up/threads/part-1/grammar" target="_blank" rel="noreferrer">语法篇：让结构服务于意思</a> ｜ <a href="https://byoungd.github.io/up/threads/part-1/1-understanding" target="_blank" rel="noreferrer">认知与训练原则</a> ｜ <a href="https://byoungd.github.io/up/templates/evidence-chain" target="_blank" rel="noreferrer">证据链模板</a></p><hr><p>来源：<a href="https://byoungd.github.io/up/templates/grammar-evidence" target="_blank" rel="noreferrer">人生进阶指南</a> · 稿件更新：2026-09-02。内容许可：<a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>。</p>',28)])])}const c=d(h,[["render",i]]);export{p as __pageData,c as default};
